// Helper to format VehiclePropValue values as string based on property type
template<typename VehiclePropValue>
inline std::string VehiclePropValue_ValueString(const VehiclePropValue& value) {
    std::ostringstream oss;
    auto type = getPropertyType(value.prop());
    
    switch (type) {
        case VehiclePropertyType::STRING:
            return value.string_value();
            
        case VehiclePropertyType::BOOLEAN:
            if (value.int32_values_size() > 0) {
                return value.int32_values(0) ? "true" : "false";
            }
            return "<empty>";
            
        case VehiclePropertyType::INT32:
            if (value.int32_values_size() > 0) {
                return std::to_string(value.int32_values(0));
            }
            return "<empty>";
            
        case VehiclePropertyType::INT32_VEC:
            oss << "[";
            for (int i = 0; i < value.int32_values_size(); ++i) {
                if (i > 0) oss << ", ";
                oss << value.int32_values(i);
            }
            oss << "]";
            return oss.str();
            
        case VehiclePropertyType::INT64:
            if (value.int64_values_size() > 0) {
                return std::to_string(value.int64_values(0));
            }
            return "<empty>";
            
        case VehiclePropertyType::INT64_VEC:
            oss << "[";
            for (int i = 0; i < value.int64_values_size(); ++i) {
                if (i > 0) oss << ", ";
                oss << value.int64_values(i);
            }
            oss << "]";
            return oss.str();
            
        case VehiclePropertyType::FLOAT:
            if (value.float_values_size() > 0) {
                return std::to_string(value.float_values(0));
            }
            return "<empty>";
            
        case VehiclePropertyType::FLOAT_VEC:
            oss << "[";
            for (int i = 0; i < value.float_values_size(); ++i) {
                if (i > 0) oss << ", ";
                oss << value.float_values(i);
            }
            oss << "]";
            return oss.str();
            
        case VehiclePropertyType::BYTES:
            oss << "<bytes:" << value.byte_values().size() << ">";
            return oss.str();
            
        case VehiclePropertyType::MIXED:
            // For MIXED types, show all non-empty fields
            oss << "{";
            if (!value.string_value().empty()) {
                oss << "str:\"" << value.string_value() << "\"";
            }
            if (value.int32_values_size() > 0) {
                oss << " i32:[";
                for (int i = 0; i < value.int32_values_size(); ++i) {
                    if (i > 0) oss << ",";
                    oss << value.int32_values(i);
                }
                oss << "]";
            }
            if (value.int64_values_size() > 0) {
                oss << " i64:[";
                for (int i = 0; i < value.int64_values_size(); ++i) {
                    if (i > 0) oss << ",";
                    oss << value.int64_values(i);
                }
                oss << "]";
            }
            if (value.float_values_size() > 0) {
                oss << " f:[";
                for (int i = 0; i < value.float_values_size(); ++i) {
                    if (i > 0) oss << ",";
                    oss << value.float_values(i);
                }
                oss << "]";
            }
            if (!value.byte_values().empty()) {
                oss << " bytes:" << value.byte_values().size();
            }
            oss << "}";
            return oss.str();
            
        default:
            return "<unknown type>";
    }
}

